import sys, os, zipfile, re, html
src, out = sys.argv[1], sys.argv[2]
os.makedirs(out, exist_ok=True)
def docx(p):
    z=zipfile.ZipFile(p); x=z.read('word/document.xml').decode('utf8')
    x=re.sub(r'</w:p>','\n',x); x=re.sub(r'<w:tab/>','\t',x); x=re.sub(r'<[^>]+>','',x)
    return html.unescape(x)
def xlsx(p):
    try:
        import openpyxl
        wb=openpyxl.load_workbook(p,data_only=True); r=[]
        for ws in wb:
            r.append(f'## sheet {ws.title} {ws.max_row}x{ws.max_column}')
            for row in ws.iter_rows(values_only=True):
                if any(c is not None for c in row): r.append(' | '.join('' if c is None else str(c) for c in row))
        return '\n'.join(r)
    except Exception as e: return f'ERR {e}'
def pdf(p):
    try:
        import pypdf
        return '\n'.join((pg.extract_text() or '') for pg in pypdf.PdfReader(p).pages)
    except Exception as e: return f'ERR {e}'
def msg(p):
    try:
        import extract_msg
        m=extract_msg.Message(p); return f'From: {m.sender}\nDate: {m.date}\nSubject: {m.subject}\n\n{m.body}'
    except Exception as e:
        b=open(p,'rb').read(); t=b.decode('utf-16-le','ignore'); return 'RAW\n'+' '.join(re.findall(r'[ -~\n]{6,}',t))[:20000]
for root,_,fs in os.walk(src):
    for f in fs:
        p=os.path.join(root,f); e=f.lower().rsplit('.',1)[-1]
        fn={'docx':docx,'xlsx':xlsx,'pdf':pdf,'msg':msg,'pptx':None}.get(e)
        if e=='pptx':
            z=zipfile.ZipFile(p); t='\n'.join(re.sub(r'<[^>]+>',' ',z.read(n).decode('utf8')) for n in sorted(z.namelist()) if n.startswith('ppt/slides/slide'))
        elif fn: t=fn(p)
        else: continue
        name=os.path.relpath(p,src).replace(os.sep,'__')+'.txt'
        open(os.path.join(out,name),'w',encoding='utf8').write(t)
        print(len(t), name)
EOF
python -I "$S/extract.py" "$CLAUDE_JOB_DIR/tmp/sas_extract/General" "$CLAUDE_JOB_DIR/tmp/sas_text"

