import sys, pypff, json, collections
f=pypff.file(); f.open(sys.argv[1]); out=[]
def walk(folder, path):
    for i in range(folder.number_of_sub_messages):
        m=folder.get_sub_message(i)
        try: body=m.plain_text_body.decode('utf8','ignore') if m.plain_text_body else ''
        except Exception: body=''
        if not body and m.html_body:
            import re,html; body=html.unescape(re.sub(r'<[^>]+>',' ',m.html_body.decode('utf8','ignore')))
        hdr=m.transport_headers or ''
        to=''; 
        for line in hdr.splitlines():
            if line.lower().startswith('to:'): to=line[3:].strip()
        out.append(dict(folder=path,subject=m.subject,sender=m.sender_name,date=str(m.delivery_time or m.client_submit_time),to=to,body=body))
    for j in range(folder.number_of_sub_folders):
        sf=folder.get_sub_folder(j); walk(sf, path+'/'+(sf.name or ''))
walk(f.get_root_folder(),'')
json.dump(out,open(sys.argv[2],'w',encoding='utf8'))
print('messages',len(out))
print(collections.Counter(o['folder'] for o in out).most_common(10))
print(collections.Counter(o['sender'] for o in out).most_common(10))
EOF
